class Solution {
public:
    int maxScore(vector<int>& nums) {
        int n = nums.size();
        vector<int> best(n);
        best[n - 1] = n - 1;
        for (int i = n - 2; i >= 0; i--)
            best[i] = nums[i] > nums[best[i + 1]] ? i : best[i + 1];
        long long ans = 0;
        int i = 0;
        while (i < n - 1) {
            int j = best[i + 1];
            ans += (long long)(j - i) * nums[j];
            i = j;
        }
        return (int)ans;
    }
};

