class Solution {
public:
    int maxScore(vector<int>& nums) {
        int n = nums.size();
        vector<long long> dp(n, 0);
        for (int i = n - 2; i >= 0; i--) {
            long long b = 0;
            for (int j = i + 1; j < n; j++)
                b = max(b, (long long)(j - i) * nums[j] + dp[j]);
            dp[i] = b;
        }
        return (int)dp[0];
    }
};

